using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Web.Script.Serialization;using DualSteam.UI;using DualSteam;
public partial class App {
 TextBlock updatesStatus;ReleaseInfo availableRelease;bool checkingUpdates;DateTime nextUpdate=DateTime.MinValue;string notifiedVersion;
 void BeginSetup(){var wizard=new SetupWizard(Engine.DetectSteam()){Owner=window};if(wizard.ShowDialog()==true)Act(()=>SetupService.Provision(wizard.SteamPath,wizard.DataPath),"Second Steam is ready. Open it and sign in to your second account.",secondCard);}
 async void CheckUpdates(bool manual=false){if(checkingUpdates)return;checkingUpdates=true;nextUpdate=DateTime.UtcNow.AddMinutes(30);if(updatesStatus!=null)updatesStatus.Text="Checking GitHub…";try{var release=await Task.Run(()=>UpdateService.GetLatest());availableRelease=release.Version>UpdateService.ParseVersion(UpdateService.CurrentVersion)?release:null;nextUpdate=DateTime.UtcNow.AddHours(6);string message=availableRelease==null?"You’re up to date. Version "+UpdateService.CurrentVersion+" is the latest stable release.":"Version "+release.Tag+" is available. Your accounts and game files will be preserved.";if(updatesStatus!=null)updatesStatus.Text=message;if(availableRelease!=null&&notifiedVersion!=release.Tag){notifiedVersion=release.Tag;ShowManager();if(MessageBox.Show(window,message+"\n\nDownload and install this update? Quit Second Steam first.","Dual Steam update",MessageBoxButton.YesNo,MessageBoxImage.Information)==MessageBoxResult.Yes)InstallUpdate();}else if(manual)toast.Show(message);}catch(Exception ex){if(updatesStatus!=null)updatesStatus.Text=ex.Message;Engine.Log("Update check: "+ex.Message);if(manual)toast.Show(ex.Message);}finally{checkingUpdates=false;}}
 async void InstallUpdate(){if(busy)return;if(availableRelease==null){CheckUpdates(true);return;}busy=true;try{var release=availableRelease;await Task.Run(()=>{if(Engine.Current!=null){var status=Engine.Status();if((status.RootIds??new int[0]).Length>0||(status.GameIds??new int[0]).Length>0)throw new IOException("Quit Second Steam and its games before installing the update. Main Steam can stay open.");try{Engine.Control("detach");}catch(System.TimeoutException){}}});if(updatesStatus!=null)updatesStatus.Text="Downloading and verifying the update…";string package=await Task.Run(()=>UpdateService.Download(release));string folder=Path.GetDirectoryName(package);var request=new UpdateRequest{Target=Engine.Home,Package=package,Sha256=release.Sha256,Version=release.Version.ToString(),ManagerPid=Process.GetCurrentProcess().Id,ManagerStartTicks=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks};string file=Path.Combine(folder,"request.json");File.WriteAllText(file,new JavaScriptSerializer().Serialize(request));string updater=Path.Combine(folder,"Dual Steam Updater.exe");File.Copy(Path.Combine(Engine.Home,"Dual Steam Updater.exe"),updater);Process.Start(new ProcessStartInfo(updater,"--request "+Engine.Quote(file)){UseShellExecute=true});exitRequested=true;window.Close();}catch(Exception ex){Engine.Log("Update install: "+ex);MessageBox.Show(window,ex.Message,"Update not installed",MessageBoxButton.OK,MessageBoxImage.Information);}finally{busy=false;}}
 FrameworkElement UpdatesPage(){var body=Stack();Heading("Updates","Stable releases from GitHub. Your profiles stay in place.",body);updatesStatus=Text("Installed version: "+UpdateService.CurrentVersion,14,"text.primary",true);body.Children.Add(Group(updatesStatus));body.Children.Add(Choice("Check for updates automatically",Preferences.Current.AutoUpdates,v=>Preferences.Current.AutoUpdates=v));body.Children.Add(Text("Checks run when the manager starts and every six hours while it is open. An available update brings the dashboard forward. Downloads are checked against GitHub’s SHA-256 digest and backed up before installation.",13,"text.secondary"));body.Children.Add(ActionButton("Check for updates",()=>CheckUpdates(true),true));body.Children.Add(ActionButton("Install available update",InstallUpdate));body.Children.Add(ActionButton("View releases on GitHub",()=>OpenPath("https://github.com/"+UpdateService.Repository+"/releases")));return body;}
 FrameworkElement AddonOptions(){var body=Stack();if(!MillenniumSharing.Detected){if(MillenniumSharing.CanDisable)body.Children.Add(ActionButton("Disable imported Millennium runtime",()=>Act(MillenniumSharing.Disable,"Imported Millennium disabled. Themes and backups were preserved.")));return body;}var choices=Stack();choices.Children.Add(Text("MILLENNIUM DETECTED",12,"text.muted",true));choices.Children.Add(Text("Import only the components you select. Quit Second Steam first. Add-ons run code inside Steam and may affect compatibility.",13,"text.secondary"));choices.Children.Add(Choice("Millennium runtime",Preferences.Current.ImportMillennium,v=>Preferences.Current.ImportMillennium=v));if(MillenniumSharing.ThemesDetected)choices.Children.Add(Choice("Installed themes",Preferences.Current.ImportThemes,v=>Preferences.Current.ImportThemes=v));if(MillenniumSharing.ConfigDetected)choices.Children.Add(Choice("Theme selection, appearance settings and custom CSS",Preferences.Current.ImportThemeSettings,v=>Preferences.Current.ImportThemeSettings=v));if(MillenniumSharing.PluginsDetected)choices.Children.Add(Choice("Installed plugins and enabled-plugin list",Preferences.Current.ImportPlugins,v=>Preferences.Current.ImportPlugins=v));choices.Children.Add(Choice("Import these selections before Second Steam starts",Preferences.Current.SyncMillennium,v=>Preferences.Current.SyncMillennium=v));choices.Children.Add(ActionButton("Import selected add-ons",()=>Act(()=>{Engine.LastLaunchNotice=MillenniumSharing.Import();},"Selected add-ons imported."),true));choices.Children.Add(Text("Steam credentials, account data, proxy credentials and unrelated loader DLLs are excluded. Originals are backed up under Backups / Millennium.",12,"text.muted"));if(MillenniumSharing.CanDisable)choices.Children.Add(ActionButton("Disable imported Millennium runtime",()=>Act(MillenniumSharing.Disable,"Imported Millennium disabled. Themes and backups were preserved.")));body.Children.Add(Group(choices));return body;}
}
